import{_ as a,b as e,e as n,a7 as d}from"./chunks/framework.CFO60l-h.js";const u=JSON.parse('{"title":"Agent 接入总览","description":"把国新学伴接进个人 Agent 的三种方式：复制提示词、上传内容包、安装 Skill。","frontmatter":{"title":"Agent 接入总览","description":"把国新学伴接进个人 Agent 的三种方式：复制提示词、上传内容包、安装 Skill。","type":"agent-index","tags":["Agent","接入","定制"],"updated":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md","lastUpdated":null}'),l={name:"agent/index.md"};function i(s,t,o,r,c,h){return e(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="把国新学伴接进你的-agent" tabindex="-1">把国新学伴接进你的 Agent <a class="header-anchor" href="#把国新学伴接进你的-agent" aria-label="Permalink to &quot;把国新学伴接进你的 Agent&quot;">​</a></h1><blockquote><p>目标：<strong>不写代码、不配 API Key、3 分钟能用</strong>。本期只做“只读检索”，不做上传/修改。</p></blockquote><h2 id="三种方式-按你的工具选" tabindex="-1">三种方式，按你的工具选 <a class="header-anchor" href="#三种方式-按你的工具选" aria-label="Permalink to &quot;三种方式，按你的工具选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的 Agent</th><th>推荐方式</th><th>你要做什么</th><th>难度</th></tr></thead><tbody><tr><td>能联网/能打开网页</td><td><strong>复制提示词</strong></td><td>复制一段话 + 站点地址</td><td>最低</td></tr><tr><td>能上传文件/知识库</td><td><strong>上传内容包</strong></td><td>下载 <code>content.md</code> 上传</td><td>低</td></tr><tr><td>支持 Skill/插件</td><td><strong>安装 Skill 包</strong></td><td>下载 zip / 粘贴安装指令</td><td>低</td></tr><tr><td>只能聊天，不能联网/上传</td><td>手动复制单页</td><td>把需要的页面内容粘进去</td><td>兜底</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">先试这个</p><p>打开你的 Agent，复制下面这段话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的“国新学伴”学习助手。请先读取这个索引：</span></span>
<span class="line"><span>https://guoxin.wxr535.cn/agent/index.json</span></span>
<span class="line"><span>然后根据我的问题，找到对应页面并阅读，回答时附上页面链接。</span></span>
<span class="line"><span>如果索引或页面打不开，请直接说“打不开”，不要编造。</span></span></code></pre></div><p>然后把 <code>https://guoxin.wxr535.cn</code> 换成你的实际域名。</p></div><h2 id="它能帮你做什么" tabindex="-1">它能帮你做什么 <a class="header-anchor" href="#它能帮你做什么" aria-label="Permalink to &quot;它能帮你做什么&quot;">​</a></h2><ul><li>查某年级培养方案的学分模块、课程学期、先修关系。</li><li>找某门课的教师、考核方式、资料清单。</li><li>按时间线梳理“我现在该准备什么”。</li><li>对照保研细则，列出材料清单和缺口。</li><li>把经验帖/面试题整理成可执行的准备计划。</li></ul><h2 id="它不能做什么" tabindex="-1">它不能做什么 <a class="header-anchor" href="#它不能做什么" aria-label="Permalink to &quot;它不能做什么&quot;">​</a></h2><ul><li>不能替代教务系统，不能认定学分/推免资格。</li><li>不能访问“申请版”保研资料（公开版已脱敏）。</li><li>不能保证回答 100% 准确；涉及关键政策，必须回到官方原文。</li></ul><h2 id="为什么本期不做-mcp-oauth" tabindex="-1">为什么本期不做 MCP/OAuth <a class="header-anchor" href="#为什么本期不做-mcp-oauth" aria-label="Permalink to &quot;为什么本期不做 MCP/OAuth&quot;">​</a></h2><p>MCP 很合适，但需要服务器、OAuth、权限和审计；两天内做不完，也会增加低代码用户的理解成本。先用<strong>静态 Agent Pack</strong>（<code>index.json</code> + <code>content.md</code> + <code>SKILL.md</code>）跑通“能查、能引用”，等站点稳定后再升级 MCP。</p><h2 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h2><ul><li>站点是公开只读的，不收集你的个人信息。</li><li>你的 Agent 可能会把问题/内容发给模型厂商；不要问个人隐私、成绩、联系方式。</li><li>公开版资料请勿截图外传；需要完整保研经验，走“申请版”。</li></ul>`,13)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
